import React, { useState } from 'react';
import axios from 'axios';

const TripDebugger = () => {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const testTripCreation = async () => {
    setLoading(true);
    setResult(null);

    const tripData = {
      trip_purpose: 'Debug test meeting',
      destination_city: 'Mumbai',
      start_date: '2025-08-23',
      end_date: '2025-08-26'
    };

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:8000/trip-budget/create-trip',
        tripData,
        { headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' } }
      );
      setResult({ success: true, status: response.status, data: response.data });
    } catch (error) {
      setResult({ success: false, status: error.response?.status || 'Network Error', error: error.response?.data || error.message });
    } finally {
      setLoading(false);
    }
  };

  const checkAuth = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/profile', { headers: { Authorization: `Bearer ${token}` } });
      setResult({ success: true, type: 'auth_check', data: response.data });
    } catch (error) {
      setResult({ success: false, type: 'auth_check', error: error.response?.data || error.message });
    } finally {
      setLoading(false);
    }
  };

  const testDebugEndpoint = async () => {
    setLoading(true);
    setResult(null);

    const tripData = {
      trip_purpose: 'Debug test meeting',
      destination_city: 'Mumbai',
      start_date: '2025-08-23',
      end_date: '2025-08-26'
    };

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:8000/trip-budget/debug-request',
        tripData,
        { headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' } }
      );
      setResult({ success: true, type: 'debug_endpoint', status: response.status, data: response.data });
    } catch (error) {
      setResult({ success: false, type: 'debug_endpoint', status: error.response?.status || 'Network Error', error: error.response?.data || error.message });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container-page">
      <div className="page-header">
        <div className="title">Trip Creation Debugger</div>
        <div className="subtitle">Use these tools to validate trip APIs and your auth session</div>
      </div>

      <div className="content-card">
        <div className="action-buttons" style={{ marginBottom: 16 }}>
          <button className="btn btn-secondary" onClick={checkAuth} disabled={loading}>🔐 Check Authentication</button>
          <button className="btn btn-secondary" onClick={testDebugEndpoint} disabled={loading}>🔍 Test Debug Endpoint</button>
          <button className="btn btn-primary" onClick={testTripCreation} disabled={loading}>🧳 Test Trip Creation</button>
        </div>

        {loading && <div className="loading-container"><div className="loading-spinner"></div><p>Loading...</p></div>}

        {result && (
          <div className={`content-card`} style={{ marginTop: 16 }}>
            <div className="page-title">{result.success ? '✅ Success' : '❌ Error'}</div>
            {result.status && <div className="text-muted">Status: {result.status}</div>}
            <pre style={{ background: '#f8f9fa', padding: 12, borderRadius: 8, overflowX: 'auto' }}>
              {JSON.stringify(result.data || result.error, null, 2)}
            </pre>
          </div>
        )}

        <div className="content-card" style={{ marginTop: 16 }}>
          <div className="page-title">Debug Info</div>
          <div className="grid grid-3">
            <div className="card"><strong>Token exists</strong><div>{localStorage.getItem('token') ? 'Yes' : 'No'}</div></div>
            <div className="card"><strong>Current URL</strong><div>{window.location.href}</div></div>
            <div className="card"><strong>User Agent</strong><div>{navigator.userAgent}</div></div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripDebugger;
